          host.dataset.ctState = JSON.stringify({ source: origin, progress, level_m: level, connectedCells: region.count, touchesBoundary: region.touchesBoundary, spillDepth_m: r.prediction.spillDepth_m, baselineDepth_m: r.baseline.spillDepth_m, observedChecksum: r.grid.depths.reduce((a, b) => a + b, 0) });
